namespace RonSijm.FluidHumidifier.Factories.ResilienceHubV2;

public class PolicyFactory(string resourceName = null, Action<Humidifier.ResilienceHubV2.Policy> factoryAction = null) : ResourceFactory<Humidifier.ResilienceHubV2.Policy>(resourceName)
{

    internal InnerPolicyMultiRegionTargetsFactory MultiRegionFactory { get; set; }

    internal InnerPolicyAvailabilitySloFactory AvailabilitySloFactory { get; set; }

    internal InnerPolicyDataRecoveryTargetsFactory DataRecoveryFactory { get; set; }

    internal InnerPolicyMultiAzTargetsFactory MultiAzFactory { get; set; }

    protected override Humidifier.ResilienceHubV2.Policy Create()
    {
        var policyResult = CreatePolicy();
        factoryAction?.Invoke(policyResult);

        return policyResult;
    }

    private Humidifier.ResilienceHubV2.Policy CreatePolicy()
    {
        var policyResult = new Humidifier.ResilienceHubV2.Policy
        {
            GivenName = InputResourceName,
        };

        return policyResult;
    }
    public override void CreateChildren(Humidifier.ResilienceHubV2.Policy result)
    {
        base.CreateChildren(result);

        result.MultiRegion ??= MultiRegionFactory?.Build();
        result.AvailabilitySlo ??= AvailabilitySloFactory?.Build();
        result.DataRecovery ??= DataRecoveryFactory?.Build();
        result.MultiAz ??= MultiAzFactory?.Build();
    }

} // End Of Class

